import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Dumbbell, Users, Trophy, Star, Clock, MapPin, Phone, Mail } from "lucide-react";
import heroImage from "@/public/assets/hero-gym.jpg";
import gymInterior from "@/public/assets/gym-interior.jpg";
import strengthTraining from "@/public/assets/strength-training.jpg";
import cardioWorkout from "@/public/public/assets/cardio-workout.jpg";
import weightLoss from "@/public/assets/weight-loss.jpg";
import functionalTraining from "@/public/assets/functional-training.jpg";
import stretchingRecovery from "@/public/assets/stretching-recovery.jpg";
import trainer1 from "@/public/assets/trainer-1.jpg";
import trainer2 from "@/public/assets/trainer-2.jpg";
import trainer3 from "@/public/assets/trainer-3.jpg";
import trainer4 from "@/public/assets/trainer-4.jpg";

const GymLanding = () => {
  return (
    <div className="min-h-screen bg-background font-display">
      {/* Hero Section */}
      <section 
        className="relative min-h-screen flex items-center justify-center bg-cover bg-center bg-no-repeat"
        style={{ backgroundImage: `linear-gradient(rgba(12, 27, 42, 0.7), rgba(12, 27, 42, 0.7)), url(${heroImage})` }}
      >
        <div className="container mx-auto px-6 text-center text-white">
          <h1 className="text-6xl md:text-8xl font-black mb-6 tracking-tight">
            BE <span className="text-primary">STRONG</span>
          </h1>
          <p className="text-xl md:text-2xl mb-8 max-w-2xl mx-auto font-medium">
            Join The Best Gym In Town
          </p>
          <Button variant="gym" size="lg" className="text-lg px-8 py-6">
            Join Now
          </Button>
        </div>
      </section>

      {/* Features Section */}
      <section className="py-20 bg-secondary">
        <div className="container mx-auto px-6">
          <div className="grid md:grid-cols-3 gap-8">
            <Card className="p-8 text-center bg-card border-border hover:shadow-card transition-all duration-300">
              <div className="w-16 h-16 bg-primary rounded-full flex items-center justify-center mx-auto mb-6 shadow-glow">
                <Users className="w-8 h-8 text-black" />
              </div>
              <h3 className="text-xl font-bold mb-4 text-foreground">Certified Trainers</h3>
              <p className="text-muted-foreground">Expert guidance from certified fitness professionals</p>
            </Card>
            <Card className="p-8 text-center bg-card border-border hover:shadow-card transition-all duration-300">
              <div className="w-16 h-16 bg-primary rounded-full flex items-center justify-center mx-auto mb-6 shadow-glow">
                <Trophy className="w-8 h-8 text-black" />
              </div>
              <h3 className="text-xl font-bold mb-4 text-foreground">Nutrition Plans</h3>
              <p className="text-muted-foreground">Customized meal plans to maximize your results</p>
            </Card>
            <Card className="p-8 text-center bg-card border-border hover:shadow-card transition-all duration-300">
              <div className="w-16 h-16 bg-primary rounded-full flex items-center justify-center mx-auto mb-6 shadow-glow">
                <Dumbbell className="w-8 h-8 text-black" />
              </div>
              <h3 className="text-xl font-bold mb-4 text-foreground">Modern Equipment</h3>
              <p className="text-muted-foreground">State-of-the-art fitness equipment and facilities</p>
            </Card>
          </div>
        </div>
      </section>

      {/* About Section */}
      <section className="py-20 bg-background">
        <div className="container mx-auto px-6">
          <div className="grid lg:grid-cols-2 gap-12 items-center">
            <div>
              <img 
                src={gymInterior} 
                alt="Modern gym interior" 
                className="rounded-lg shadow-card grayscale hover:grayscale-0 transition-all duration-500"
              />
            </div>
            <div>
              <h2 className="text-4xl md:text-5xl font-black mb-6 text-foreground">
                About Our <span className="text-primary">Gym</span>
              </h2>
              <p className="text-lg text-muted-foreground mb-8 leading-relaxed">
                Transform your body and mind at our world-class fitness facility. With cutting-edge equipment, 
                expert trainers, and a supportive community, we're here to help you achieve your fitness goals.
              </p>
              <Button variant="gym" size="lg" className="mr-4">
                Learn More
              </Button>
              <Button variant="gymOutline" size="lg">
                Contact Us
              </Button>
            </div>
          </div>
        </div>
      </section>

      {/* Programs Section */}
      <section className="py-20 bg-secondary">
        <div className="container mx-auto px-6">
          <h2 className="text-4xl md:text-5xl font-black text-center mb-16 text-foreground">
            Our <span className="text-primary">Programs</span>
          </h2>
          <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-8">
            {[
              { image: strengthTraining, title: "Strength Training", description: "Build muscle and power" },
              { image: cardioWorkout, title: "Cardio", description: "Improve endurance" },
              { image: weightLoss, title: "Weight Loss", description: "Burn fat effectively" },
              { image: functionalTraining, title: "Functional", description: "Real-world movements" },
            ].map((program, index) => (
              <Card key={index} className="overflow-hidden bg-card border-border hover:shadow-card transition-all duration-300 group">
                <div className="relative overflow-hidden">
                  <img 
                    src={program.image} 
                    alt={program.title}
                    className="w-full h-48 object-cover group-hover:scale-110 transition-transform duration-500"
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent" />
                </div>
                <div className="p-6">
                  <h3 className="text-xl font-bold mb-2 text-foreground">{program.title}</h3>
                  <p className="text-muted-foreground mb-4">{program.description}</p>
                  <Button variant="gym" size="sm">
                    Learn More
                  </Button>
                </div>
              </Card>
            ))}
          </div>
        </div>
      </section>

      {/* CTA Section */}
      <section 
        className="py-32 bg-cover bg-center bg-no-repeat relative"
        style={{ backgroundImage: `linear-gradient(rgba(12, 27, 42, 0.8), rgba(12, 27, 42, 0.8)), url(${stretchingRecovery})` }}
      >
        <div className="container mx-auto px-6 text-center">
          <h2 className="text-4xl md:text-6xl font-black mb-8 text-white">
            Ready to Transform Your Life?
          </h2>
          <p className="text-xl text-white/90 mb-8 max-w-2xl mx-auto">
            Join thousands of members who have already transformed their bodies and minds
          </p>
          <Button variant="gym" size="lg" className="text-lg px-8 py-6">
            Get Started Today
          </Button>
        </div>
      </section>

      {/* Pricing Section */}
      <section className="py-20 bg-background">
        <div className="container mx-auto px-6">
          <h2 className="text-4xl md:text-5xl font-black text-center mb-16 text-foreground">
            Choose Your <span className="text-primary">Plan</span>
          </h2>
          <div className="grid md:grid-cols-3 gap-8 max-w-6xl mx-auto">
            {[
              { name: "Basic", price: "$29", features: ["Gym Access", "Locker Room", "Basic Support"] },
              { name: "Premium", price: "$59", features: ["Everything in Basic", "Group Classes", "Personal Trainer Session"], popular: true },
              { name: "Elite", price: "$99", features: ["Everything in Premium", "Unlimited PT Sessions", "Nutrition Consultation", "Priority Booking"] },
            ].map((plan, index) => (
              <Card key={index} className={`p-8 relative ${plan.popular ? 'border-primary shadow-glow' : 'border-border'} bg-card`}>
                {plan.popular && (
                  <div className="absolute -top-4 left-1/2 transform -translate-x-1/2">
                    <div className="bg-primary text-black px-4 py-2 rounded-full text-sm font-bold">
                      Most Popular
                    </div>
                  </div>
                )}
                <div className="text-center mb-8">
                  <h3 className="text-2xl font-bold mb-2 text-foreground">{plan.name}</h3>
                  <div className="text-4xl font-black text-primary mb-2">{plan.price}</div>
                  <div className="text-muted-foreground">per month</div>
                </div>
                <ul className="space-y-4 mb-8">
                  {plan.features.map((feature, idx) => (
                    <li key={idx} className="flex items-center">
                      <Star className="w-5 h-5 text-primary mr-3" />
                      <span className="text-foreground">{feature}</span>
                    </li>
                  ))}
                </ul>
                <Button variant={plan.popular ? "gym" : "gymOutline"} className="w-full">
                  Choose Plan
                </Button>
              </Card>
            ))}
          </div>
        </div>
      </section>

      {/* Team Section */}
      <section className="py-20 bg-secondary">
        <div className="container mx-auto px-6">
          <h2 className="text-4xl md:text-5xl font-black text-center mb-16 text-foreground">
            Meet Our <span className="text-primary">Trainers</span>
          </h2>
          <div className="grid md:grid-cols-4 gap-8">
            {[
              { image: trainer1, name: "Mike Johnson", role: "Head Trainer" },
              { image: trainer2, name: "Sarah Wilson", role: "Fitness Coach" },
              { image: trainer3, name: "David Brown", role: "Strength Coach" },
              { image: trainer4, name: "Lisa Garcia", role: "Wellness Expert" },
            ].map((trainer, index) => (
              <div key={index} className="text-center">
                <div className="relative mb-6 group">
                  <img 
                    src={trainer.image} 
                    alt={trainer.name}
                    className="w-48 h-48 rounded-full mx-auto object-cover shadow-card group-hover:shadow-glow transition-all duration-300"
                  />
                </div>
                <h3 className="text-xl font-bold mb-2 text-foreground">{trainer.name}</h3>
                <p className="text-primary font-semibold">{trainer.role}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Contact Section */}
      <section className="py-20 bg-background">
        <div className="container mx-auto px-6">
          <div className="grid lg:grid-cols-2 gap-12 items-center">
            <div>
              <img 
                src={stretchingRecovery} 
                alt="Fitness consultation" 
                className="rounded-lg shadow-card"
              />
            </div>
            <div>
              <h2 className="text-4xl md:text-5xl font-black mb-8 text-foreground">
                Get In <span className="text-primary">Touch</span>
              </h2>
              <form className="space-y-6">
                <div className="grid md:grid-cols-2 gap-4">
                  <Input placeholder="Full Name" className="bg-secondary border-border" />
                  <Input placeholder="Email" type="email" className="bg-secondary border-border" />
                </div>
                <Input placeholder="Phone Number" className="bg-secondary border-border" />
                <Textarea placeholder="Message" rows={5} className="bg-secondary border-border" />
                <Button variant="gym" size="lg" className="w-full">
                  Send Message
                </Button>
              </form>
            </div>
          </div>
        </div>
      </section>

      {/* Blog Section */}
      <section className="py-20 bg-secondary">
        <div className="container mx-auto px-6">
          <h2 className="text-4xl md:text-5xl font-black text-center mb-16 text-foreground">
            Latest <span className="text-primary">Blog Posts</span>
          </h2>
          <div className="grid md:grid-cols-2 gap-8 max-w-4xl mx-auto">
            <Card className="overflow-hidden bg-card border-border hover:shadow-card transition-all duration-300">
              <img 
                src={strengthTraining} 
                alt="Blog post" 
                className="w-full h-48 object-cover"
              />
              <div className="p-6">
                <div className="text-primary text-sm font-semibold mb-2">January 15, 2024</div>
                <h3 className="text-xl font-bold mb-4 text-foreground">5 Essential Strength Training Tips for Beginners</h3>
                <p className="text-muted-foreground mb-4">
                  Discover the fundamental principles of strength training that will help you build muscle safely and effectively.
                </p>
                <Button variant="gym" size="sm">
                  Read More
                </Button>
              </div>
            </Card>
            <Card className="overflow-hidden bg-card border-border hover:shadow-card transition-all duration-300">
              <img 
                src={cardioWorkout} 
                alt="Blog post" 
                className="w-full h-48 object-cover"
              />
              <div className="p-6">
                <div className="text-primary text-sm font-semibold mb-2">January 10, 2024</div>
                <h3 className="text-xl font-bold mb-4 text-foreground">The Ultimate Guide to Cardio Training</h3>
                <p className="text-muted-foreground mb-4">
                  Learn how to maximize your cardiovascular fitness with these proven cardio techniques and strategies.
                </p>
                <Button variant="gym" size="sm">
                  Read More
                </Button>
              </div>
            </Card>
          </div>
        </div>
      </section>

      {/* Footer */}
      <footer className="bg-primary py-12">
        <div className="container mx-auto px-6">
          <div className="grid md:grid-cols-4 gap-8 mb-8">
            <div>
              <h3 className="text-2xl font-black text-black mb-4">PowerGym</h3>
              <p className="text-black/80">
                Transform your life with our world-class fitness programs and expert guidance.
              </p>
            </div>
            <div>
              <h4 className="font-bold text-black mb-4">Quick Links</h4>
              <ul className="space-y-2">
                <li><a href="#" className="text-black/80 hover:text-black">About</a></li>
                <li><a href="#" className="text-black/80 hover:text-black">Programs</a></li>
                <li><a href="#" className="text-black/80 hover:text-black">Trainers</a></li>
                <li><a href="#" className="text-black/80 hover:text-black">Contact</a></li>
              </ul>
            </div>
            <div>
              <h4 className="font-bold text-black mb-4">Contact Info</h4>
              <div className="space-y-2">
                <div className="flex items-center">
                  <Phone className="w-4 h-4 text-black mr-2" />
                  <span className="text-black/80">(555) 123-4567</span>
                </div>
                <div className="flex items-center">
                  <Mail className="w-4 h-4 text-black mr-2" />
                  <span className="text-black/80">info@powergym.com</span>
                </div>
                <div className="flex items-center">
                  <MapPin className="w-4 h-4 text-black mr-2" />
                  <span className="text-black/80">123 Fitness St, City</span>
                </div>
              </div>
            </div>
            <div>
              <h4 className="font-bold text-black mb-4">Hours</h4>
              <div className="space-y-2">
                <div className="flex items-center">
                  <Clock className="w-4 h-4 text-black mr-2" />
                  <span className="text-black/80">Mon-Fri: 5AM-11PM</span>
                </div>
                <div className="text-black/80 ml-6">Sat-Sun: 7AM-9PM</div>
              </div>
            </div>
          </div>
          <div className="border-t border-black/20 pt-8 text-center">
            <p className="text-black/80">© 2024 PowerGym. All rights reserved.</p>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default GymLanding;